<?php
namespace ProjectPress\Includes\Project\Core;
use ProjectPress\Includes\Core\WP\Database; use ProjectPress\Includes\Pages\Taxonomies; use WP_Error;
if(!defined('ABSPATH')){exit;}
final class ProjectClassificationRepository{public static function allowed_taxonomies():array{return array(Taxonomies::PROJECT_TYPE,Taxonomies::PROJECT_CATEGORY,Taxonomies::PROJECT_TAG,Taxonomies::PROJECT_LABEL);}public function terms(string $taxonomy):array{if(!in_array($taxonomy,self::allowed_taxonomies(),true))return array();$terms=get_terms(array('taxonomy'=>$taxonomy,'hide_empty'=>false,'meta_key'=>'_pp_sort_order','orderby'=>'meta_value_num','order'=>'ASC'));return is_wp_error($terms)?array():$terms;}public function assigned_term_ids(int $project_id,string $taxonomy):array{if($project_id<1||!in_array($taxonomy,self::allowed_taxonomies(),true))return array();global $wpdb;$rows=$wpdb->get_col($wpdb->prepare('SELECT term_id FROM '.Database::table_name('project_term_relationships').' WHERE project_id = %d AND taxonomy = %s',$project_id,$taxonomy));return array_values(array_unique(array_map('absint',(array)$rows)));}public function create_term(string $taxonomy,string $name,array $data=array()){if(!in_array($taxonomy,self::allowed_taxonomies(),true))return new WP_Error('projectpress_invalid_taxonomy',__('Invalid project classification.','projectpress'));$result=wp_insert_term($name,$taxonomy,array('slug'=>sanitize_title($data['slug']??$name),'description'=>sanitize_textarea_field($data['description']??''),'parent'=>absint($data['parent']??0)));if(is_wp_error($result))return $result;$id=(int)$result['term_id'];update_term_meta($id,'_pp_colour',sanitize_hex_color($data['colour']??'')?:'');update_term_meta($id,'_pp_icon',sanitize_key($data['icon']??''));update_term_meta($id,'_pp_sort_order',absint($data['sort_order']??0));update_term_meta($id,'_pp_enabled',empty($data['enabled'])?0:1);return get_term($id,$taxonomy);}public function assign(int $project_id,string $taxonomy,array $term_ids):bool{if($project_id<1||!in_array($taxonomy,self::allowed_taxonomies(),true))return false;global $wpdb;$table=Database::table_name('project_term_relationships');$wpdb->delete($table,array('project_id'=>$project_id,'taxonomy'=>$taxonomy),array('%d','%s'));foreach(array_unique(array_map('absint',$term_ids)) as $term_id){$term=get_term($term_id,$taxonomy);if(!$term||is_wp_error($term))continue;$wpdb->insert($table,array('project_id'=>$project_id,'term_id'=>$term_id,'taxonomy'=>$taxonomy,'assigned_by'=>get_current_user_id(),'assigned_at'=>current_time('mysql',true)),array('%d','%d','%s','%d','%s'));}return true;}}
